import { openai } from "@ai-sdk/openai";
import { convertToModelMessages, isStepCount, streamText, type UIMessage } from "ai";
import { lookupOrder } from "@/lib/tools/orders";
import { refundPolicy } from "@/lib/tools/policy";

export const maxDuration = 30;

export async function POST(request: Request) {
  const { messages }: { messages: UIMessage[] } = await request.json();
  const result = streamText({
    model: openai("gpt-5-mini"),
    system: "You answer order questions for the Lumen Lamps shop. Look orders up before answering.",
    messages: await convertToModelMessages(messages),
    tools: { lookupOrder, refundPolicy },
    stopWhen: isStepCount(5),
    onError({ error }) {
      console.error("chat stream failed", error);
    },
  });
  return result.toUIMessageStreamResponse();
}

