import { readFile } from "node:fs/promises";

type Page = { title: string; body: string };

const pages: Page[] = JSON.parse(await readFile(new URL("./pages.json", import.meta.url), "utf8"));

export function searchDocs(query: string, limit: number) {
  const terms = query.toLowerCase().split(/\s+/);
  return pages
    .map((page) => ({ page, score: terms.filter((term) => page.body.toLowerCase().includes(term)).length }))
    .filter((hit) => hit.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map(({ page }) => ({ title: page.title, excerpt: page.body.slice(0, 400) }));
}

