import { generateText, isStepCount } from "ai";
import { lookupOrder } from "@/lib/tools/orders";
import { refundPolicy } from "@/lib/tools/policy";

const shared = { tools: { lookupOrder, refundPolicy } };

// The nightly digest reuses the chat configuration but must never act.
export async function digest(transcript: string) {
  const { text } = await generateText({
    model: openai("gpt-5-mini"),
    prompt: `Summarize today's support conversations:\n${transcript}`,
    tools: shared.tools,
    toolChoice: "none",
    stopWhen: isStepCount(2),
  });
  return text;
}

