import datetime as dt

BOOKED: dict[str, set[str]] = {}


def free_slots(day: str) -> list[str]:
    dt.date.fromisoformat(day)
    taken = BOOKED.get(day, set())
    return [f"{hour:02d}:{minute:02d}" for hour in range(9, 17) for minute in (0, 30) if f"{hour:02d}:{minute:02d}" not in taken]


def book_slot(day: str, slot: str, attendee: str) -> str:
    if slot not in free_slots(day):
        return f"{slot} on {day} is no longer free"
    BOOKED.setdefault(day, set()).add(slot)
    return f"booked {slot} on {day} with {attendee}"

