from pydantic import BaseModel
from pydantic_ai import Agent, RunContext

from ledger import Ledger


@dataclass
class Deps:
    ledger: Ledger
    employee_id: str


class Verdict(BaseModel):
    approved: bool
    reason: str


reviewer = Agent(
    "openai:gpt-5-mini",
    deps_type=Deps,
    output_type=Verdict,
    instructions="Approve an expense only if it fits the employee's remaining monthly budget.",
)


@reviewer.tool
def remaining_budget(ctx: RunContext[Deps]) -> float:
    """Remaining monthly budget of the employee, in euros."""
    return ctx.deps.ledger.remaining(ctx.deps.employee_id)


def review(ledger: Ledger, employee_id: str, claim: str) -> Verdict:
    return reviewer.run_sync(claim, deps=Deps(ledger, employee_id)).output

