class Ledger:
    def __init__(self, budgets: dict[str, float], spent: dict[str, float]) -> None:
        self.budgets = budgets
        self.spent = spent

    def remaining(self, employee_id: str) -> float:
        return self.budgets.get(employee_id, 0.0) - self.spent.get(employee_id, 0.0)

