"""Answer questions about the on-call rota by calling local functions."""

import json

from openai import OpenAI

from rota import who_is_on_call, swap_requests

client = OpenAI()
FUNCTIONS = {"who_is_on_call": who_is_on_call, "swap_requests": swap_requests}
TOOLS = [
    {
        "type": "function",
        "function": {
            "name": "who_is_on_call",
            "description": "Engineer on call for a team on a date",
            "parameters": {
                "type": "object",
                "properties": {"team": {"type": "string"}, "date": {"type": "string"}},
                "required": ["team", "date"],
            },
        },
    },
    {
        "type": "function",
        "function": {
            "name": "swap_requests",
            "description": "Open swap requests for a team",
            "parameters": {"type": "object", "properties": {"team": {"type": "string"}}, "required": ["team"]},
        },
    },
]


def ask(question: str) -> str:
    messages = [{"role": "user", "content": question}]
    for _ in range(6):
        response = client.chat.completions.create(model="gpt-5-mini", messages=messages, tools=TOOLS)
        message = response.choices[0].message
        messages.append(message)
        if not message.tool_calls:
            return message.content or ""
        for call in message.tool_calls:
            result = FUNCTIONS[call.function.name](**json.loads(call.function.arguments))
            messages.append({"role": "tool", "tool_call_id": call.id, "content": json.dumps(result)})
    return "stopped after six tool rounds"

